    names: ['Nova', 'Orion', 'Vega', 'Marte', 'Cometa', 'Luna', 'Sirio', 'Astro', 'Cosmo', 'Pulsar', 'Quasar', 'Titan'],
    accessories: ['lentes', 'corona', 'ninguno'],
  },
